def transform(grid):
    """Complete each partial copy of the color-4 pattern."""
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    master_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not master_cells:
        return out
    r0 = min(r for r, c in master_cells)
    c0 = min(c for r, c in master_cells)
    shape = {(r-r0, c-c0) for r, c in master_cells}
    colors = {grid[r][c] for r in range(h) for c in range(w)} - {1, 4}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Find the translation of the master shape that contains every observed pixel.
        candidates = {(pts[0][0]-sr, pts[0][1]-sc) for sr, sc in shape}
        for r, c in pts[1:]:
            candidates &= {(r-sr, c-sc) for sr, sc in shape}
        if not candidates:
            continue
        # The partial pattern identifies one translated copy; retain deterministic fallback.
        ar, ac = sorted(candidates)[0]
        for sr, sc in shape:
            rr, cc = ar+sr, ac+sc
            if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 1:
                out[rr][cc] = color
    return out

