    c0 = min(c for r, c in master_cells)
    shape = {(r-r0, c-c0) for r, c in master_cells}

    # A color can mark more than one partial copy. Group nearby marks into
    # instances; sparse marks in one instance can be separated by two cells.
    for color in {grid[r][c] for r in range(h) for c in range(w)} - {1, 4}:
        remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        groups = []
        while remaining:
            group = {remaining.pop()}
            changed = True
            while changed:
                changed = False
                for pt in list(remaining):
                    if any(max(abs(pt[0]-q[0]), abs(pt[1]-q[1])) <= 2 for q in group):
                        group.add(pt)
                        remaining.remove(pt)
                        changed = True
            groups.append(group)
        for pts in groups:
            pts = list(pts)
            candidates = {(pts[0][0]-sr, pts[0][1]-sc) for sr, sc in shape}
            for r, c in pts[1:]:
                candidates &= {(r-sr, c-sc) for sr, sc in shape}
            if not candidates:
                continue
            ar, ac = sorted(candidates)[0]
            for sr, sc in shape:
